export const DPIA_HOOK_CONTEXT_BLOCK: string =
"// ── [RATIFY] — the direction matrix (doc 213 §4, amended by doc 222 §3 and\n// doc 224), as data — VERBATIM COPY of LIA_HOOK_DIRECTION_MATRIX. See that\n// file's own header: this table exists only so a byte-pin test can catch\n// drift between the DATA and the CODE (`directionFor`, hook-types.ts, the\n// shared, product-agnostic module both products' joins call). ─────────────\n\nexport interface DpiaHookMatrixRow {\n  readonly posture: string;\n  readonly fact_agreement: string;\n  readonly engine_verdict: string;\n  readonly shape: string;\n  readonly note: string;\n}\n\nexport const DPIA_HOOK_DIRECTION_MATRIX: readonly DpiaHookMatrixRow[] = [\n  {\n    posture: \"accepted\",\n    fact_agreement: \"same\",\n    engine_verdict: \"any\",\n    shape: \"S1 supports\",\n    note: \"hedged to `likely` language; never lifts a determination\",\n  },\n  {\n    posture: \"accepted\",\n    fact_agreement: \"different / unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"nothing to say\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"same\",\n    engine_verdict: \"passes, and every condition_atom holds on the record\",\n    shape: \"S5b recognised + condition satisfied\",\n    note: \"the engine's pass is what satisfies the condition; the hook only echoes it (doc 222 §3)\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"same\",\n    engine_verdict: \"otherwise (fails / uncertain, or condition_atoms null / not all held)\",\n    shape: \"S5a recognised, condition unresolved\",\n    note: \"the guidance is relevant; whether its condition is met is Section {section}'s question — never asserted here (the doc 218 D1 defect)\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"different (a distinguishing pair holds)\",\n    engine_verdict: \"passes\",\n    shape: \"omit + assessor flag `authority_not_dispositive` (`rule_missing` when the pair expressly excludes)\",\n    note: \"a silent source under a pass is nothing missing; an express exclusion under a pass is the lawyer's rule\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"different (a distinguishing pair holds)\",\n    engine_verdict: \"fails / uncertain\",\n    shape: \"S6 source silent (S6x where the pair expressly excludes)\",\n    note: \"\\\"does not extend\\\" only from an authored `source_expressly_excludes` pair with a verified exclusion span (doc 222 §2.4)\",\n  },\n  {\n    posture: \"conditional\",\n    fact_agreement: \"unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"same\",\n    engine_verdict: \"fails / uncertain\",\n    shape: \"S2 cuts against and applied\",\n    note: \"the determination already reflects it\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"same\",\n    engine_verdict: \"passes\",\n    shape: \"omit + assessor flag `rule_missing`\",\n    note:\n      \"the lawyer's rule: an adverse authority on the same facts under a pass means a rule is missing — never printed as \\\"risk noted\\\"\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"different (a distinguishing pair holds)\",\n    engine_verdict: \"any\",\n    shape: \"S3 cuts against but distinguished\",\n    note: \"renders only from the pair (source fact / record fact); never from an atom's generic phrase\",\n  },\n  {\n    posture: \"rejected\",\n    fact_agreement: \"unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"\",\n  },\n  {\n    posture: \"contested (R4)\",\n    fact_agreement: \"same\",\n    engine_verdict: \"any\",\n    shape: \"S4 noted as a boundary\",\n    note: \"prints the derived status and the appeal note; no relation drawn\",\n  },\n  {\n    posture: \"contested (R4)\",\n    fact_agreement: \"different / unknown\",\n    engine_verdict: \"any\",\n    shape: \"omit\",\n    note: \"a contested decision on different facts adds nothing (doc 222 §3)\",\n  },\n  {\n    posture: \"any\",\n    fact_agreement: \"unknown from atoms\",\n    engine_verdict: \"—\",\n    shape: \"the stored two-leg selection's agreement, if one exists; else omit + flag `selection_pending`; legs disagreed → omit + flag `selection_unsettled` (the ROO item)\",\n    note: \"doc 224 §1: a call is made only where no stored decision exists AND the pre-filter says either answer could print\",\n  },\n  {\n    posture: \"any\",\n    fact_agreement: \"`required_atoms` not all held\",\n    engine_verdict: \"—\",\n    shape: \"not nominated\",\n    note: \"\",\n  },\n];\n\n// ── [RATIFY — DRAFT, unratified] — the atom-phrase map (doc 213 §5 pattern;\n// this build's own DPIA vocabulary, doc 232). One ratified clause per\n// closed-list atom value in HOOK_PRODUCT_REGISTRY.dpia\n// (generate-corpus-hooks/_local/product-registry.ts). ──────────────────────\n\nexport const DPIA_ATOM_PHRASES: Readonly<Record<string, string>> = {\n  // — classes —\n  \"class:employee_monitoring\": \"the processing monitors employees\",\n  \"class:public_space_surveillance\": \"the processing systematically monitors a publicly accessible area\",\n  \"class:algorithmic_decision\": \"the processing includes automated evaluation, scoring, or decision-making\",\n  \"class:innovative_technology_use\": \"the processing uses a novel or innovative technology\",\n  \"class:dataset_matching\": \"the processing matches or combines datasets\",\n\n  // — flags —\n  \"flag:biometric\": \"the processing includes biometric data\",\n  \"flag:special_category\": \"the processing includes special-category data\",\n  \"flag:children\": \"children are among the people affected\",\n  \"flag:large_scale\": \"the processing is carried out on a large scale\",\n  \"flag:vulnerable_subjects\": \"the processing concerns vulnerable data subjects\",\n  \"flag:automated_decision\": \"the processing involves automated decision-making\",\n  \"flag:cross_border_transfer\": \"the processing involves a cross-border transfer of personal data\",\n\n  // — relationships —\n  \"relationship:employee\": \"the people affected are employees of the controller\",\n  \"relationship:customer\": \"the people affected are customers of the controller\",\n  \"relationship:public\": \"the people affected are members of the public with no relationship to the controller\",\n\n  // — data categories (DPIA_DATA_CATEGORIES / DATA_CATS, DPIAFramework.enums.ts) —\n  \"data_category:Contact details\": \"the processing includes contact details\",\n  \"data_category:Employee records\": \"the processing includes employee records\",\n  \"data_category:Customer records\": \"the processing includes customer records\",\n  \"data_category:Health or medical data\": \"the processing includes health or medical data\",\n  \"data_category:Financial data\": \"the processing includes financial data\",\n  \"data_category:Biometric data\": \"the processing includes biometric data\",\n  \"data_category:Children's data\": \"the processing includes children's data\",\n  \"data_category:Location data\": \"the processing includes location data\",\n  \"data_category:Communications content\": \"the processing includes communications content\",\n  \"data_category:Other\": \"the processing includes other categories of data not separately listed\",\n\n  // — instruments —\n  \"instrument:EU GDPR\": \"the processing is assessed under the EU GDPR\",\n  \"instrument:UK GDPR\": \"the processing is assessed under the UK GDPR\",\n\n  // — state: atoms — the closed `reasons_to_conduct` vocabulary (17 options,\n  // REASONS_TO_CONDUCT / DPIAFramework.enums.ts), true and false phrasing for\n  // each (the `false` form is the only way to phrase an ABSENCE — the doc 223\n  // defect this build designs out from day one: a hook may distinguish on a\n  // record that DID NOT select a reason only through this explicit `=false`\n  // phrase, never by reusing the `=true` phrase for an absent-polarity pair).\n  \"state:intake.reasons_to_conduct.art35_3a_evaluation_profiling=true\":\n    \"the record selects systematic, extensive evaluation or profiling with significant effects as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.art35_3a_evaluation_profiling=false\":\n    \"the record does not select systematic, extensive evaluation or profiling with significant effects as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.art35_3b_large_scale_special_category=true\":\n    \"the record selects large-scale special-category or criminal-offence data as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.art35_3b_large_scale_special_category=false\":\n    \"the record does not select large-scale special-category or criminal-offence data as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.art35_3c_public_area_monitoring=true\":\n    \"the record selects large-scale systematic monitoring of a public area as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.art35_3c_public_area_monitoring=false\":\n    \"the record does not select large-scale systematic monitoring of a public area as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.evaluation_scoring=true\":\n    \"the record selects evaluation or scoring, including profiling or prediction, as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.evaluation_scoring=false\":\n    \"the record does not select evaluation or scoring as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.automated_decision_making=true\":\n    \"the record selects automated decision-making with a legal or significant effect as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.automated_decision_making=false\":\n    \"the record does not select automated decision-making with a legal or significant effect as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.systematic_monitoring=true\":\n    \"the record selects systematic monitoring of employees, a defined population, or a non-public space as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.systematic_monitoring=false\":\n    \"the record does not select systematic monitoring of employees, a defined population, or a non-public space as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.sensitive_data=true\":\n    \"the record selects sensitive or highly personal data as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.sensitive_data=false\":\n    \"the record does not select sensitive or highly personal data as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.large_scale=true\":\n    \"the record selects data processed on a large scale as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.large_scale=false\":\n    \"the record does not select data processed on a large scale as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.matching_combining_datasets=true\":\n    \"the record selects matching or combining datasets as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.matching_combining_datasets=false\":\n    \"the record does not select matching or combining datasets as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.vulnerable_subjects=true\":\n    \"the record selects data concerning vulnerable subjects as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.vulnerable_subjects=false\":\n    \"the record does not select data concerning vulnerable subjects as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.innovative_technology=true\":\n    \"the record selects innovative use of new technology as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.innovative_technology=false\":\n    \"the record does not select innovative use of new technology as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.prevents_exercising_right=true\":\n    \"the record selects that the processing prevents exercising a right or using a service as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.prevents_exercising_right=false\":\n    \"the record does not select that the processing prevents exercising a right or using a service as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.required_by_national_law=true\":\n    \"the record selects that the assessment is required by national law\",\n  \"state:intake.reasons_to_conduct.required_by_national_law=false\":\n    \"the record does not select that the assessment is required by national law\",\n  \"state:intake.reasons_to_conduct.dpo_or_data_subject_recommendation=true\":\n    \"the record selects a DPO or data-subject recommendation as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.dpo_or_data_subject_recommendation=false\":\n    \"the record does not select a DPO or data-subject recommendation as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.required_by_code_of_conduct=true\":\n    \"the record selects that the assessment is required by a code of conduct or standard\",\n  \"state:intake.reasons_to_conduct.required_by_code_of_conduct=false\":\n    \"the record does not select that the assessment is required by a code of conduct or standard\",\n  \"state:intake.reasons_to_conduct.risk_management_accountability=true\":\n    \"the record selects risk management or accountability as a (beneficial, non-mandatory) reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.risk_management_accountability=false\":\n    \"the record does not select risk management or accountability as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.existing_processing_risk_changed=true\":\n    \"the record selects that this is existing processing whose risk has changed as a reason the assessment was undertaken\",\n  \"state:intake.reasons_to_conduct.existing_processing_risk_changed=false\":\n    \"the record does not select that this is existing processing whose risk has changed as a reason the assessment was undertaken\",\n};\n\n// ── [RATIFY — DRAFT, unratified] — the sentence shapes (doc 213 §5 pattern\n// as amended by doc 222 §4), DPIA-specific text. Slot NAMES are identical to\n// LIA's shapes (dpia-hook-join.ts's renderer needs no product-specific\n// branching); the WORDING differs where LIA's is legitimate-interest-\n// specific (doc 232 build brief: \"S5a/S5b/S6/S6x wording is LIA-specific …\n// draft DPIA-appropriate shape text\"). ─────────────────────────────────────\n\n// DOC 238 (2026-09-09) — AMENDED, still [RATIFY — DRAFT, unratified]: doc 237\n// §5 found no current shape, in any product, can produce any CEO-approved\n// hook sentence (docs 223B/233/234/236). This revision (a) restructures\n// every shape from a 2–4-sentence clause template into the approved\n// 4–7-sentence paragraph form, (b) adds the `{quote}` slot (the verified\n// `finding_span`, wrapped in quotation marks by the template — quote marks\n// are ratified template text, never drafted content, so no verify.ts change\n// is needed), (c) adds the optional `{governing_provision}` slot to S1–S4\n// (S5a/S5b/S6/S6x already carry an equivalent rule statement via\n// `{proposition}`/`{condition}`), and (d) rewords S2/S6x's section pointer\n// from backward-asserting (\"…and the determination in Section {section}\n// reflects it\") to forward-looking (\"Whether that holds… is addressed in\n// Section {section}\") — matching every approved DPIA candidate this session\n// (233 §\"AENA\": \"Section 3 addresses whether that analysis is present\";\n// §\"ICS\": \"Section 1 records whether that trigger is satisfied\"). S1 is left\n// backward-asserting on purpose (doc 233's WP248 candidate: \"supports the\n// assessment's position… Section 1 records that determination\" — a\n// SUPPORTING finding is properly asserted, not hedged as pending). The hedge\n// itself is NOT template text — see `DPIA_HEDGE_DOMESTIC_FACTS_PROPOSED`\n// below, appended by the join exactly like `DPIA_APPEAL_SENTENCE`. See doc\n// 238 §\"DPIA\" for the full proposal, a rendered example, and the CEO\n// ratify/revise/hold line.\n\nexport const DPIA_HOOK_SHAPES: Readonly<Record<\"S1\" | \"S2\" | \"S3\" | \"S4\" | \"S5a\" | \"S5b\" | \"S6\" | \"S6x\", string>> = {\n  S1:\n    \"The record identifies that {customer_fact}. In {authority}, {regulator} {verb} that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding supports the assessment's position on {factor}. Section {section} records that determination. ({citation}; {status}.)\",\n  S2:\n    \"The record identifies that {customer_fact}. In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding cuts against the assessment's position on {factor}. Whether that holds on this record is addressed in Section {section}. ({citation}; {status}.)\",\n  S3:\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". That finding turned on the fact that {source_fact}; on this record the assessment has instead identified {record_fact}. The decision marks a boundary rather than a finding against the record. ({citation}; {status}.)\",\n  S4:\n    \"In {authority}, {regulator} found that where {fact_pattern}, {finding} — in its own words, \\\"{quote}\\\". The record identifies {customer_fact}. That decision is {status}; it is noted as a boundary and is not applied. ({citation}.)\",\n  S5a:\n    \"In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}. That guidance is relevant to {factor}; whether its condition is satisfied is addressed in Section {section}. ({citation}; {status}.)\",\n  S5b:\n    \"In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}. That guidance is relevant to {factor}; whether its condition is satisfied is addressed in Section {section}. The facts identified in Section {section} satisfy that stated condition. ({citation}; {status}.)\",\n  S6:\n    \"The record identifies {record_fact}. In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}, but does not address whether the same conclusion follows where {record_fact}. The determination in Section {section} therefore rests on the separately identified rules and facts, not on that guidance. ({citation}; {status}.)\",\n  S6x:\n    \"The record identifies {record_fact}. In {authority}, {regulator} {verb} that {proposition} — in its own words, \\\"{quote}\\\" — subject to {condition}, and that {exclusion_paraphrase}; that exclusion applies to processing of the kind the record describes. Whether it applies here is addressed on {factor} in Section {section}. ({citation}; {status}.)\",\n};\n\n// ── [RATIFY — DRAFT, unratified] — concept equivalence (doc 222 §2.3\n// pattern). Two atoms naming the same underlying fact share a concept; the\n// render dedupes `{customer_fact}` by concept. ────────────────────────────\n\nexport const DPIA_ATOM_CONCEPTS: Readonly<Record<string, string>> = {\n  \"flag:special_category\": \"special_category\",\n  \"data_category:Health or medical data\": \"special_category\",\n  \"state:intake.reasons_to_conduct.art35_3b_large_scale_special_category=true\": \"special_category\",\n  \"flag:children\": \"children\",\n  \"data_category:Children's data\": \"children\",\n  \"state:intake.reasons_to_conduct.vulnerable_subjects=true\": \"vulnerable_subjects\",\n  \"flag:vulnerable_subjects\": \"vulnerable_subjects\",\n  \"flag:biometric\": \"biometric\",\n  \"data_category:Biometric data\": \"biometric\",\n  \"flag:large_scale\": \"large_scale\",\n  \"state:intake.reasons_to_conduct.large_scale=true\": \"large_scale\",\n  \"flag:automated_decision\": \"automated_decision\",\n  \"class:algorithmic_decision\": \"automated_decision\",\n  \"state:intake.reasons_to_conduct.automated_decision_making=true\": \"automated_decision\",\n  \"class:employee_monitoring\": \"employee_monitoring\",\n  \"state:intake.reasons_to_conduct.systematic_monitoring=true\": \"employee_monitoring\",\n};\n\n/** The concept an atom names — itself when the table has no entry. */\nexport function dpiaAtomConcept(atom: string): string {\n  return DPIA_ATOM_CONCEPTS[atom] ?? atom;\n}\n\n// ── [RATIFY — DRAFT, unratified] — factor phrases (doc 222 §5 pattern): the\n// `{factor}` slot, without a leading article. Every factor maps to exactly\n// one of DPIA's two hook elements (`DPIA_FACTOR_ELEMENT`, below) — doc 232's\n// factor/determination → section map. ──────────────────────────────────────\n\nconst F_OBLIGATION = \"the Article 35 obligation to conduct this assessment\";\nconst F_EMPLOYEE_MONITORING = \"the employee-monitoring trigger\";\nconst F_ALGORITHMIC = \"the automated-decision trigger\";\nconst F_ADEQUACY = \"the necessity and proportionality analysis\";\nconst F_BIOMETRIC_ADEQUACY = \"the adequacy of the biometric-processing analysis\";\n\nexport const DPIA_FACTOR_PHRASES: Readonly<Record<string, string>> = {\n  [F_OBLIGATION]: \"the obligation to conduct this assessment\",\n  [F_EMPLOYEE_MONITORING]: \"the employee-monitoring trigger\",\n  [F_ALGORITHMIC]: \"the automated-decision trigger\",\n  [F_ADEQUACY]: \"necessity and proportionality\",\n  [F_BIOMETRIC_ADEQUACY]: \"the adequacy of the biometric-processing analysis\",\n};\n\n// ── [RATIFY — DRAFT, unratified] — DOC 213 §2 pattern: factor → DPIA hook\n// element (\"obligation\" | \"adequacy\" — dpia-hook-join.ts's\n// `SECTION_FOR_ELEMENT`/`bears_on_element`). Copied verbatim into\n// generate-corpus-hooks/_local/dpia-factor-element.ts (pinned by test), the\n// same relationship LIA_FACTOR_ELEMENT has to\n// generate-corpus-hooks/_local/factor-element.ts. ──────────────────────────\n\nexport const DPIA_FACTOR_ELEMENT: Readonly<Record<string, \"obligation\" | \"adequacy\">> = {\n  [F_OBLIGATION]: \"obligation\",\n  [F_EMPLOYEE_MONITORING]: \"obligation\",\n  [F_ALGORITHMIC]: \"obligation\",\n  [F_ADEQUACY]: \"adequacy\",\n  [F_BIOMETRIC_ADEQUACY]: \"adequacy\",\n};\n\nexport function dpiaElementOf(factorId: string): \"obligation\" | \"adequacy\" | null {\n  return DPIA_FACTOR_ELEMENT[factorId] ?? null;\n}\n\n// ── [RATIFY] — source status labels (doc 222 §2.7) — VERBATIM COPY of\n// LIA_SOURCE_STATUS_LABELS. Product-agnostic: HookSourceStatus\n// (hook-types.ts) carries no LIA-specific vocabulary. ──────────────────────\n\nexport const DPIA_SOURCE_STATUS_LABELS: Readonly<Record<string, string>> = {\n  edpb_guidelines_final: \"EDPB guidelines — interpretive guidance, not binding law\",\n  edpb_opinion: \"EDPB Article 64 opinion — Board opinion, not a judicial decision\",\n  wp29_opinion: \"Article 29 Working Party opinion — historical interpretive guidance\",\n  regulator_guidance: \"regulatory guidance — non-binding\",\n  sa_decision: \"supervisory-authority decision — persuasive, non-binding outside its jurisdiction\",\n  sa_decision_affirmed: \"supervisory-authority decision, affirmed on appeal\",\n  sa_decision_appeal_pending: \"under appeal\",\n};\n\n// ── RATIFIED (LIA, CEO 2026-09-08) — BYTE-MIRRORED here, unchanged. Where an\n// appeal is known to have been made, the join appends this sentence,\n// verbatim, after the hook's sentence. ─────────────────────────────────────\n\nexport const DPIA_APPEAL_SENTENCE = \"This matter is subject to an appeal which could invalidate this ruling.\";\n\n// ── [RATIFY — DRAFT, unratified] — DOC 238 §5 item 4, PROPOSED. The hedge\n// clause, mirroring DPIA_APPEAL_SENTENCE's pattern exactly: a fixed string,\n// appended by the join, never drafted. DPIA uses ONLY the domestic-facts\n// hedge — every one of its sources (EDPB/WP29 guidance, EU/UK enforcement\n// decisions) applies the SAME governing law (EU/UK GDPR) DPIA itself\n// assesses, so there is no \"foreign law\" hedge variant for this product\n// (unlike Risk/ADMT, where a GDPR enforcement decision is foreign relative\n// to California law). Matches every approved candidate this session: doc\n// 233's own repeated \"But the outcome depends on this company's own facts:\n// …\" clause. Wording here is GENERIC (hook-agnostic) rather than the\n// hand-tailored fact list each approved candidate carries — see doc 238\n// §\"DPIA\" for that judgment call, flagged for the CEO. ────────────────────\n\nexport const DPIA_HEDGE_DOMESTIC_FACTS_PROPOSED =\n  \"But the outcome here depends on this company's own facts, not on the cited authority's.\";\n\nexport const DPIA_SETTLEDNESS_LABELS: Readonly<Record<\"R1\" | \"R2\" | \"R3\" | \"R4\", string>> = {\n  R1: \"adopted guidance or settled authority\",\n  R2: \"a settled line of decisions\",\n  R3: \"a single supervisory authority's decision\",\n  R4: \"under appeal / contested\",\n};\n";
